pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value, bytes memory data, address nonOwner) public {
        // 1. Restrict to admissible domain: nonOwner cannot be the deployer (owner) nor the zero address.
        address originalOwner = c.owner();
        vm.assume(nonOwner != originalOwner);
        vm.assume(nonOwner != address(0));
        vm.assume(target != address(c)); // prevent self-call edge cases that might break invariant
        // bound value to avoid overflow but still allow draining
        vm.assume(value <= address(c).balance + 1000 ether);

        // 2. Set up: fund the contract directly so it has balance to test.
        vm.deal(originalOwner, 10 ether);
        vm.prank(originalOwner);
        (bool success,) = address(c).call{value: 10 ether}("");
        require(success, "funding failed");

        // Drive sendMoney as the original owner (adversarial counterparty is not needed here;
        // the bug is about access control, not about external call failure/revert/reentrancy).
        vm.prank(originalOwner);
        try c.sendMoney(target, value, data) {} catch {}

        // 3. Now a nonOwner attempts withdrawAll; capture whether it succeeded.
        bool nonOwnerSucceeded;
        vm.prank(nonOwner);
        try c.withdrawAll() { nonOwnerSucceeded = true; } catch { nonOwnerSucceeded = false; }

        // General rule: Only the owner can successfully call withdrawAll.
        // The correct contract satisfies: nonOwner withdrawAll always fails.
        // The buggy contract allows nonOwner to succeed for some input (e.g., when balance > 0).
        assertTrue(!nonOwnerSucceeded);
    }
}

