contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount, bytes memory data) public {
        // 1. Restrict the domain: target must be a contract (not an EOA) to ensure reverts can happen.
        vm.assume(target.code.length > 0);
        // amount must be > 0 to test balance changes
        vm.assume(amount > 0);
        // Ensure the contract has enough balance to send
        vm.deal(address(c), amount);
        // 2. Deploy an adversarial helper that reverts on receive, ensuring sendMoney always fails.
        Reverter reverter = new Reverter();
        // Use the reverter's address as the target for sendMoney
        address revertTarget = address(reverter);
        // Prepare data that triggers the fallback (empty bytes is fine)
        bytes memory callData = "";
        // Owner calls sendMoney to the reverter; this should always revert.
        vm.prank(c.owner());
        bool sendReverted = false;
        try c.sendMoney(revertTarget, amount, callData) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }
        // The sendMoney must have reverted (target reverts), so contract balance remains unchanged.
        require(sendReverted, "sendMoney should revert");
        // 3. Now a non-owner tries to withdraw the full balance via the public withdraw function.
        // Buggy version allows this; correct version should revert because onlyOwner modifier is missing.
        address nonOwner = makeAddr("nonOwner");
        vm.prank(nonOwner);
        bool withdrawReverted = false;
        try c.withdraw(amount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        // ASSERT: In the reference, a non-owner call to withdraw must revert (protected by onlyOwner).
        // The buggy version lacks the modifier, so it succeeds, causing a difference in revert behavior.
        assertTrue(withdrawReverted, "Non-owner should not be able to withdraw");
    }
}

