pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bytes memory data) public {
        // Keep amount within sensible bounds to avoid balance underflow issues
        vm.assume(amount <= address(this).balance);
        vm.deal(address(this), amount);

        // Deploy adversarial callee that reverts on receiving Ether with data
        RevertingCallee callee = new RevertingCallee();

        // Record balance before
        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount();

        // Attempt sendMoney to the reverting callee as owner
        vm.prank(c.owner());
        (bool success, ) = address(c).call{value: amount}(
            abi.encodeWithSelector(c.sendMoney.selector, address(callee), amount, data)
        );

        // Reference behavior: if callee reverts, sendMoney MUST revert entirely
        // Buggy behavior: .transfer ignores revert, succeeds but callee rejects
        if (success) {
            // If call succeeded, reference would mean callee accepted; check invariant
            // But callee always reverts, so success means buggy version didn't revert
            // In buggy version, Ether is sent via .transfer which succeeds but callee reverts
            // leading to Ether loss and invariant violation
            assertTrue(address(c).balance == balanceBefore - amount);
        } else {
            // Reference: revert means no state change
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}

contract RevertingCallee {
    fallback() external payable {
        revert("RevertingCallee: always reverts on receive");
    }
}

